from itertools import product
def try_rule(g, seeds, Pset, vs, Ks, up=False):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    for r,c in seeds:
        for v in vs:
            for k in Ks:
                base=(r+k*v[0], c+k*v[1])
                for dr,dc in Pset:
                    i,j=base[0]+dr, base[1]+dc
                    if 0<=i<H and 0<=j<W: out[i][j]=5
    # optionally also paint mirror versions per seed
    return out
